-- 세트 561. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set561.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 561, '큰 테이블 안전하게 바꾸기: 온라인 DDL(ALGORITHM·LOCK), 배치 삭제, 내보내기·가져오기', '12만 건짜리 테이블을 서비스 중에 바꾸고 정리하는 연습입니다. ALGORITHM=INSTANT 로 컬럼 추가, 지원하지 않는 변경에 ALGORITHM·LOCK 을 지정했을 때 오류로 멈추는 것 확인, ALGORITHM=COPY 로 타입 변경, ALGORITHM=INPLACE·LOCK=NONE 으로 인덱스 추가, DELETE ... LIMIT 반복으로 오래된 행을 나눠 삭제, INTO OUTFILE 으로 내보내기와 LOAD DATA INFILE 으로 CSV 가져오기를 익힙니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 561);
UPDATE quest_set SET display_order = 821, unit_id = (SELECT id FROM unit WHERE id = 45), icon = '🧱' WHERE id = 561;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 1, '컬럼 추가는 즉시 끝나게', '`shop.orders`(12만 건)에 `memo VARCHAR(20)` 컬럼을 추가합니다. `ALTER TABLE` 은 방식(`ALGORITHM`)에 따라 표를 통째로 복사해 오래 걸릴 수도, 메타데이터만 바꿔 즉시 끝날 수도 있습니다. 서버가 **표를 복사하지 않는 가장 가벼운 방식**으로만 처리하도록 `ALGORITHM` 옵션을 지정해 컬럼을 추가하세요. (그 방식이 불가능하면 서버가 느리게 하는 대신 오류를 냅니다.)', '`ALTER TABLE ... ADD COLUMN ..., ALGORITHM=값` 형식입니다. 값은 COPY(전체 복사)·INPLACE(제자리)·그리고 가장 가벼운 이름(즉시)이 있습니다.', 'mariadb shop -e ''ALTER TABLE orders ADD COLUMN memo VARCHAR(20) NULL, ALGORITHM=INSTANT''
mariadb shop -e ''DESC orders''

# INSTANT 는 데이터를 건드리지 않고 정의만 바꿔 12만 건이든 1억 건이든 순식간에 끝난다. 지원하지 않는 변경이면 오류로 알려 준다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL, created_at DATE NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount, created_at) SELECT seq % 1000, seq % 500, IF(seq <= 100000, \\"2020-01-01\\", \\"2026-01-01\\") FROM seq_1_to_120000; CREATE TABLE imp (id INT, name VARCHAR(20), qty INT) ENGINE=InnoDB;''; rm -f /tmp/*.csv /tmp/*.txt; printf ''1,Kim,10\\\\n2,Lee,20\\\\n3,Park,30\\\\n'' > /tmp/in.csv; chmod 644 /tmp/in.csv"]', '["sh", "-c", "( [ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name=''memo''\\")\\" = 1 ] ) && ( [ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM orders'')\\" = 120000 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "memo 컬럼이 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name=''memo''\\")\\" = 1 ]"]}, {"label": "주문 12만 건이 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM orders'')\\" = 120000 ]"]}]', '[{"title": "InnoDB 온라인 DDL", "url": "https://mariadb.com/kb/en/innodb-online-ddl-overview/"}, {"title": "LOAD DATA INFILE", "url": "https://mariadb.com/kb/en/load-data-infile/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 2, '지원하지 않는 방식을 지정하면 오류로 멈춘다', '`amount` 컬럼의 타입을 `INT` 에서 `BIGINT` 로 바꾸려 합니다. 서비스 중이니 **표를 읽고 쓰는 것을 막지 않는 방식**(`ALGORITHM=INPLACE, LOCK=NONE`)을 요구해서 실행해 보세요. 이 방식으로 타입 변경이 되는지 **오류 메시지를 `/tmp/err.txt`** 에 저장하세요. (테이블은 바뀌지 않아야 합니다.)', '`ALTER TABLE orders MODIFY amount BIGINT NOT NULL, ALGORITHM=..., LOCK=...` 입니다. 오류는 표준 에러(`2>`)로 저장합니다.', 'mariadb shop -e ''ALTER TABLE orders MODIFY amount BIGINT NOT NULL, ALGORITHM=INPLACE, LOCK=NONE'' 2> /tmp/err.txt
cat /tmp/err.txt

# ERROR 1846 ... Cannot change column type. 방식을 지정하면 서버가 몰래 느린(표를 잠그는) 방식으로 바꾸지 않고 거절한다. 서비스를 지키는 안전장치', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL, created_at DATE NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount, created_at) SELECT seq % 1000, seq % 500, IF(seq <= 100000, \\"2020-01-01\\", \\"2026-01-01\\") FROM seq_1_to_120000; CREATE TABLE imp (id INT, name VARCHAR(20), qty INT) ENGINE=InnoDB;''; rm -f /tmp/*.csv /tmp/*.txt; printf ''1,Kim,10\\\\n2,Lee,20\\\\n3,Park,30\\\\n'' > /tmp/in.csv; chmod 644 /tmp/in.csv"]', '["sh", "-c", "( grep -q 1846 /tmp/err.txt ) && ( [ \\"$(mariadb -N -e \\"SELECT data_type FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name=''amount''\\")\\" = int ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "오류 1846 이 기록됐다", "cmd": ["sh", "-c", "grep -q 1846 /tmp/err.txt"]}, {"label": "amount 는 아직 int 다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT data_type FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name=''amount''\\")\\" = int ]"]}]', '[{"title": "InnoDB 온라인 DDL", "url": "https://mariadb.com/kb/en/innodb-online-ddl-overview/"}, {"title": "LOAD DATA INFILE", "url": "https://mariadb.com/kb/en/load-data-infile/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 3, '안 되는 변경은 COPY 로, 시간을 골라서', '앞 문제에서 보듯 타입 변경은 표를 복사해서 새로 만드는 `ALGORITHM=COPY` 만 가능합니다. 복사하는 동안 쓰기가 막힐 수 있으니 서비스가 한가한 시간에 합니다. `amount` 를 `BIGINT NOT NULL` 로 **COPY 방식으로 바꾸세요.** 12만 건은 그대로 있어야 합니다.', '`MODIFY` 뒤에 `ALGORITHM=COPY` 를 붙입니다. 끝나면 `information_schema.columns` 의 `data_type` 으로 확인할 수 있습니다.', 'mariadb shop -e ''ALTER TABLE orders MODIFY amount BIGINT NOT NULL, ALGORITHM=COPY''
mariadb -N -e "SELECT data_type FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name=''amount''"

# COPY 는 새 테이블을 만들어 행을 모두 옮긴 뒤 바꿔치기한다. 큰 테이블은 오래 걸리고 디스크도 두 배 가까이 필요하다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL, created_at DATE NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount, created_at) SELECT seq % 1000, seq % 500, IF(seq <= 100000, \\"2020-01-01\\", \\"2026-01-01\\") FROM seq_1_to_120000; CREATE TABLE imp (id INT, name VARCHAR(20), qty INT) ENGINE=InnoDB;''; rm -f /tmp/*.csv /tmp/*.txt; printf ''1,Kim,10\\\\n2,Lee,20\\\\n3,Park,30\\\\n'' > /tmp/in.csv; chmod 644 /tmp/in.csv"]', '["sh", "-c", "( [ \\"$(mariadb -N -e \\"SELECT data_type FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name=''amount''\\")\\" = bigint ] ) && ( [ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM orders'')\\" = 120000 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "amount 가 bigint 다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT data_type FROM information_schema.columns WHERE table_schema=''shop'' AND table_name=''orders'' AND column_name=''amount''\\")\\" = bigint ]"]}, {"label": "12만 건이 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM orders'')\\" = 120000 ]"]}]', '[{"title": "InnoDB 온라인 DDL", "url": "https://mariadb.com/kb/en/innodb-online-ddl-overview/"}, {"title": "LOAD DATA INFILE", "url": "https://mariadb.com/kb/en/load-data-infile/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 4, '인덱스는 읽기·쓰기를 막지 않고 추가', '`customer_id` 인덱스를 **제자리 방식으로, 읽기·쓰기를 막지 않게**(`ALGORITHM=INPLACE, LOCK=NONE`) 추가하세요. 이 방식을 지정하면 불가능할 때 오류로 알려 주므로, 성공했다면 서비스를 막지 않았다는 뜻입니다. 인덱스 이름은 `idx_cust` 로 합니다.', '`ALTER TABLE ... ADD INDEX 이름 (컬럼), ALGORITHM=..., LOCK=...` 입니다. 인덱스 추가는 대부분 이 방식이 가능합니다.', 'mariadb shop -e ''ALTER TABLE orders ADD INDEX idx_cust (customer_id), ALGORITHM=INPLACE, LOCK=NONE''
mariadb shop -e ''SHOW INDEX FROM orders''

# 인덱스 추가는 읽기·쓰기를 허용하는 온라인 DDL 이다. 다만 진행 중에는 CPU·디스크를 쓰고, 시작과 끝에 짧은 메타데이터 락이 필요하다(558)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL, created_at DATE NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount, created_at) SELECT seq % 1000, seq % 500, IF(seq <= 100000, \\"2020-01-01\\", \\"2026-01-01\\") FROM seq_1_to_120000; CREATE TABLE imp (id INT, name VARCHAR(20), qty INT) ENGINE=InnoDB;''; rm -f /tmp/*.csv /tmp/*.txt; printf ''1,Kim,10\\\\n2,Lee,20\\\\n3,Park,30\\\\n'' > /tmp/in.csv; chmod 644 /tmp/in.csv"]', '["sh", "-c", "( [ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=''shop'' AND table_name=''orders'' AND index_name=''idx_cust'' AND column_name=''customer_id''\\")\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "idx_cust 가 있다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=''shop'' AND table_name=''orders'' AND index_name=''idx_cust'' AND column_name=''customer_id''\\")\\" = 1 ]"]}]', '[{"title": "InnoDB 온라인 DDL", "url": "https://mariadb.com/kb/en/innodb-online-ddl-overview/"}, {"title": "LOAD DATA INFILE", "url": "https://mariadb.com/kb/en/load-data-infile/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 5, '오래된 행은 나눠서 지운다', '`orders` 에는 `created_at` 이 **2025-01-01 이전**인 오래된 주문 10만 건과 최근 주문 2만 건이 있습니다. 한 번의 `DELETE` 로 10만 건을 지우면 긴 트랜잭션이 되어 락·복제 지연 문제가 생깁니다. **한 번에 10000건씩** 오래된 행만 지우는 `DELETE` 를 **더 지울 행이 없을 때까지 반복**하세요.

지우는 데 성공한 `DELETE` 의 횟수(지운 행이 1건 이상인 횟수)를 `/tmp/batches.txt` 에 저장하세요. (숫자만. 최근 2만 건은 남아야 합니다.)', '`DELETE` 가 끝난 뒤 방금 지운 행 수를 알려 주는 함수가 있습니다(같은 접속에서). 그 값이 0 이 될 때까지 같은 문장을 반복하세요.', 'n=0
while :; do r=$(mariadb -N shop -e "DELETE FROM orders WHERE created_at < ''2025-01-01'' LIMIT 10000; SELECT ROW_COUNT()" | tail -1); [ "$r" = 0 ] && break; n=$((n+1)); done
echo $n > /tmp/batches.txt
cat /tmp/batches.txt

# 10 번 지운다. 작은 단위로 나누면 락과 undo 가 짧게 유지되고, 사이에 복제 지연을 살피거나 잠깐 쉴 수 있다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL, created_at DATE NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount, created_at) SELECT seq % 1000, seq % 500, IF(seq <= 100000, \\"2020-01-01\\", \\"2026-01-01\\") FROM seq_1_to_120000; CREATE TABLE imp (id INT, name VARCHAR(20), qty INT) ENGINE=InnoDB;''; rm -f /tmp/*.csv /tmp/*.txt; printf ''1,Kim,10\\\\n2,Lee,20\\\\n3,Park,30\\\\n'' > /tmp/in.csv; chmod 644 /tmp/in.csv"]', '["sh", "-c", "( mariadb -N shop -e ''SELECT COUNT(*) FROM orders WHERE created_at < ''2025-01-01'''' | grep -qx 0 ) && ( mariadb -N shop -e ''SELECT COUNT(*) FROM orders WHERE created_at >= ''2025-01-01'''' | grep -qx 20000 ) && ( [ \\"$(cat /tmp/batches.txt)\\" = 10 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "오래된 행이 모두 지워졌다", "cmd": ["sh", "-c", "mariadb -N shop -e ''SELECT COUNT(*) FROM orders WHERE created_at < ''2025-01-01'''' | grep -qx 0"]}, {"label": "최근 2만 건은 남았다", "cmd": ["sh", "-c", "mariadb -N shop -e ''SELECT COUNT(*) FROM orders WHERE created_at >= ''2025-01-01'''' | grep -qx 20000"]}, {"label": "10번에 나눠 지웠다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/batches.txt)\\" = 10 ]"]}]', '[{"title": "InnoDB 온라인 DDL", "url": "https://mariadb.com/kb/en/innodb-online-ddl-overview/"}, {"title": "LOAD DATA INFILE", "url": "https://mariadb.com/kb/en/load-data-infile/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 6, '조회 결과를 CSV 파일로 내보내기', '`orders` 의 **`id` 가 가장 작은 5건**의 `id`, `customer_id`, `amount` 세 열을 쉼표(`,`)로 구분해 **`/tmp/export.csv`** 파일로 서버에서 바로 내보내세요. (`SELECT ... INTO OUTFILE` 을 씁니다. 같은 이름의 파일이 이미 있으면 거절됩니다.)', '`SELECT 열들 FROM 테이블 ORDER BY id LIMIT 5 INTO OUTFILE ''경로'' FIELDS TERMINATED BY '',''` 형식입니다. 파일은 서버가 만들어 줍니다.', 'mariadb shop -e "SELECT id, customer_id, amount FROM orders ORDER BY id LIMIT 5 INTO OUTFILE ''/tmp/export.csv'' FIELDS TERMINATED BY '',''"
cat /tmp/export.csv

# 서버(mysql 사용자)가 직접 파일을 쓰므로 FILE 권한과 쓰기 가능한 경로가 필요하다. 운영 서버는 secure_file_priv 가 경로를 제한하는 경우가 많다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL, created_at DATE NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount, created_at) SELECT seq % 1000, seq % 500, IF(seq <= 100000, \\"2020-01-01\\", \\"2026-01-01\\") FROM seq_1_to_120000; CREATE TABLE imp (id INT, name VARCHAR(20), qty INT) ENGINE=InnoDB;''; rm -f /tmp/*.csv /tmp/*.txt; printf ''1,Kim,10\\\\n2,Lee,20\\\\n3,Park,30\\\\n'' > /tmp/in.csv; chmod 644 /tmp/in.csv"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/export.csv)\\" -eq 5 ] ) && ( [ \\"$(head -1 /tmp/export.csv)\\" = \\"1,1,1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 5줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/export.csv)\\" -eq 5 ]"]}, {"label": "첫 줄이 1,1,1 이다", "cmd": ["sh", "-c", "[ \\"$(head -1 /tmp/export.csv)\\" = \\"1,1,1\\" ]"]}]', '[{"title": "InnoDB 온라인 DDL", "url": "https://mariadb.com/kb/en/innodb-online-ddl-overview/"}, {"title": "LOAD DATA INFILE", "url": "https://mariadb.com/kb/en/load-data-infile/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 7, 'CSV 파일을 테이블로 가져오기', '`/tmp/in.csv` 에 헤더 없이 쉼표로 구분된 데이터 세 줄(열 순서는 id, name, qty)이 있습니다. 이 파일을 **`LOAD DATA INFILE`** 로 `shop.imp` 테이블(`id`, `name`, `qty`)에 가져오세요. 한 건씩 `INSERT` 하는 것보다 훨씬 빠른 대량 입력 방법입니다.', '`LOAD DATA INFILE ''경로'' INTO TABLE 테이블 FIELDS TERMINATED BY '',''` 입니다. 파일의 구분자가 쉼표임을 알려 줘야 합니다.', 'mariadb shop -e "LOAD DATA INFILE ''/tmp/in.csv'' INTO TABLE imp FIELDS TERMINATED BY '',''"
mariadb shop -e ''SELECT * FROM imp''

# 서버가 읽는 파일이라 서버에서 접근 가능한 경로여야 한다. 내 PC 의 파일은 LOAD DATA LOCAL INFILE 을 쓴다(보안상 기본 제한이 있을 수 있음)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount INT NOT NULL, created_at DATE NOT NULL) ENGINE=InnoDB; INSERT INTO orders (customer_id, amount, created_at) SELECT seq % 1000, seq % 500, IF(seq <= 100000, \\"2020-01-01\\", \\"2026-01-01\\") FROM seq_1_to_120000; CREATE TABLE imp (id INT, name VARCHAR(20), qty INT) ENGINE=InnoDB;''; rm -f /tmp/*.csv /tmp/*.txt; printf ''1,Kim,10\\\\n2,Lee,20\\\\n3,Park,30\\\\n'' > /tmp/in.csv; chmod 644 /tmp/in.csv"]', '["sh", "-c", "( [ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM imp'')\\" = 3 ] ) && ( [ \\"$(mariadb -N shop -e \\"SELECT name FROM imp WHERE id=2\\")\\" = Lee ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "세 건이 들어갔다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e ''SELECT COUNT(*) FROM imp'')\\" = 3 ]"]}, {"label": "값이 맞다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N shop -e \\"SELECT name FROM imp WHERE id=2\\")\\" = Lee ]"]}]', '[{"title": "InnoDB 온라인 DDL", "url": "https://mariadb.com/kb/en/innodb-online-ddl-overview/"}, {"title": "LOAD DATA INFILE", "url": "https://mariadb.com/kb/en/load-data-infile/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 8, '큰 DELETE 를 한 번에 하면 안 되는 이유', '운영 테이블에서 수백만 건을 `DELETE FROM t WHERE ...;` 한 문장으로 지우면 위험합니다. 가장 알맞은 이유는?', '문장 하나가 끝날 때까지 트랜잭션이 하나로 이어진다는 점을 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["DELETE 는 한 번에 최대 1만 건까지만 지워서 오류가 난다", "지운 데이터는 즉시 디스크에서 사라져 되돌릴 수 없다", "긴 트랜잭션 하나가 되어 많은 행을 오래 잠그고 복제 지연도 생긴다", "DELETE 문은 인덱스가 있으면 실행되지 않는다"]', 2, '큰 DELETE 는 한 트랜잭션으로 수많은 행에 락을 잡고 undo 로그를 쌓으며, 복제에서도 한꺼번에 적용되어 지연을 만듭니다. LIMIT 으로 나눠 반복하면 락이 짧고, 사이에 부하를 살필 수 있습니다. 행 수 제한 같은 것은 없고, DELETE 는 롤백이 가능하며 인덱스는 오히려 도움이 됩니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 9, 'ALGORITHM 을 지정하는 이유', '`ALTER TABLE ... ALGORITHM=INPLACE, LOCK=NONE` 처럼 방식을 명시하는 가장 큰 이점은 무엇인가요?', '지정하지 않으면 서버가 알아서 고르는데, 그 선택이 서비스에 부담이 될 수 있습니다.', NULL, NULL, '[]', 'choice', '["어떤 변경이든 항상 더 빨리 끝나고 복제 지연도 없다", "불가능한 방식이면 몰래 느린 방식으로 넘어가지 않고 오류로 멈춘다", "디스크를 전혀 쓰지 않아 용량 걱정이 없어진다", "인덱스를 자동으로 모두 정리해 용량을 줄여 준다"]', 1, '방식을 명시하면 서버가 그 방식을 못 쓸 때 조용히 COPY 로 바꾸지 않고 오류를 냅니다. 덕분에 실수로 서비스를 오래 막는 일을 사전에 막을 수 있습니다. 항상 빠르다는 보장은 없고, 변경마다 디스크·복제 영향은 다릅니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 10, '나눠서 지우기', '오래된 행을 한 번에 1만 건씩만 지우도록 빈칸에 들어갈 절을 채우세요.', '결과 행 수를 제한하는 절입니다.', NULL, NULL, '[]', 'fill', '["LIMIT", "OFFSET", "TOP", "FETCH"]', NULL, 'MariaDB 의 `DELETE` 는 `LIMIT` 로 한 번에 지울 행 수를 제한할 수 있습니다. `OFFSET` 은 건너뛰기, `TOP` 은 SQL Server, `FETCH` 는 표준 SQL 의 조회 구문이라 DELETE 에서는 쓰지 않습니다.', '[0]', 'DELETE FROM orders WHERE created_at < ''2025-01-01'' {0} 10000;', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 561, 11, '오래된 데이터를 안전하게 지우는 순서', '운영 테이블에서 오래된 데이터를 지우는 안전한 절차입니다. 지우기 전에 대상을 확인하고, 작은 단위로 반복하며, 끝나면 결과를 확인하는 흐름으로 놓으세요.', '지우기 전과 후에 같은 지표를 보면 의도한 범위만 지워졌는지 알 수 있습니다.', NULL, NULL, '[]', 'order', '["삭제가 끝난 뒤 남은 건수를 다시 확인", "지울 대상 건수를 SELECT COUNT(*) 로 먼저 확인", "삭제된 행이 0 이 될 때까지 반복", "조건에 맞는 행을 LIMIT 으로 나눠 DELETE 실행"]', NULL, '먼저 SELECT COUNT(*) 로 대상이 의도한 범위인지 확인합니다. 그다음 LIMIT 으로 나눠 지우고, 영향받은 행이 0 이 될 때까지 반복합니다. 마지막으로 남은 건수를 확인해 기대와 같은지 검증합니다.', '[1, 3, 2, 0]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 561 AND order_index = 11);
